-- Fuente: PDF aportado. San Carlos corregido por el usuario a Avenida Las Nieves Oriente 0812.
-- Conserva IDs e historiales; no elimina ni reactiva clases existentes.
BEGIN;
DO $$ DECLARE r record; n integer; clase uuid; BEGIN
FOR r IN SELECT * FROM jsonb_to_recordset($directorio$[{"name":"Templo Matriz","address":"Av. Concha y Toro 0256","maps_url":"https://goo.gl/maps/CYunSbnueWQTPkyy9","kind":"Templo matriz","commune":"Puente Alto"},{"name":"Concha y Toro","address":"Charles Aranjuez 044 (ex Circunvalación)","maps_url":"https://goo.gl/maps/CCTHnDLq98Hgos5t9","kind":"Local","commune":"Puente Alto"},{"name":"Los Lirios","address":"San Pedro 781","maps_url":"https://goo.gl/maps/Kjv6BXH9DqH1gHpU6","kind":"Local","commune":"Puente Alto"},{"name":"San Pedro","address":"San Juan 10676","maps_url":"https://goo.gl/maps/SyPvSrPM5X5BTu4M6","kind":"Clase","commune":"La Florida"},{"name":"Gabriela Poniente","address":"Huentelauquen 1058. Acceso al condominio por Huentelauquen con Juan de Dios Malebran.","maps_url":"https://maps.app.goo.gl/Q78xobehTk5w1sv77","kind":"Clase","commune":"Puente Alto"},{"name":"Gabriela Oriente","address":"El Hidalgo 3440","maps_url":"https://goo.gl/maps/ZjLNgLcbtas6jgoX8","kind":"Clase","commune":"Puente Alto"},{"name":"Creta Norte","address":"Cabo de Hornos 2118, Los Aromos","maps_url":"https://goo.gl/maps/QtdcWHssxquAv25V9","kind":"Clase","commune":"Puente Alto"},{"name":"Andes del Sur","address":"Cerro Abanico 3675 (Av. México con El Peral, Plaza la Ballena)","maps_url":"https://goo.gl/maps/LvZPiCHaHpL2HVXa6","kind":"Clase","commune":"Puente Alto"},{"name":"México","address":"El Libertador 10711","maps_url":"https://maps.app.goo.gl/4n15NrBAcpwPuAwL6","kind":"Clase","commune":"La Florida"},{"name":"La Foresta","address":"Los Lingues 2347","maps_url":"https://goo.gl/maps/VWvY9hP9p3GMUuTHA","kind":"Clase","commune":"Puente Alto"},{"name":"Casas Viejas","address":"27 de Septiembre esquina Los Maquis","maps_url":"https://goo.gl/maps/5URXKrWkkQhHZ4X66","kind":"Clase","commune":"Puente Alto"},{"name":"Los Andes","address":"Las Golondrinas 0441, esquina Las Tórtolas","maps_url":"https://goo.gl/maps/s36EVJaP3FkcpMBm6","kind":"Clase","commune":"Puente Alto"},{"name":"Carol Urzúa","address":"Domingo Tocornal 0935","maps_url":"https://goo.gl/maps/eGMeRNfEfdN8Zm9F9","kind":"Clase","commune":"Puente Alto"},{"name":"Central","address":"Luis Matte Larraín 0546","maps_url":"https://goo.gl/maps/AadT6dNFQXNFoEYRA","kind":"Clase","commune":"Puente Alto"},{"name":"San Carlos","address":"Avenida Las Nieves Oriente 0812","maps_url":"https://goo.gl/maps/L5cjpqGU2WPeGYcG9","kind":"Clase","commune":"Puente Alto"},{"name":"San Ramón","address":"Concha y Toro 01277","maps_url":"https://goo.gl/maps/EnurmTf8ve6rhRy3A","kind":"Clase","commune":"Puente Alto"},{"name":"Las Brisas","address":"Eyzaguirre esquina Ejército Libertador","maps_url":"https://goo.gl/maps/c3pJRD7HhGV5iQ3j6","kind":"Clase","commune":"Puente Alto"},{"name":"San Guillermo","address":"El Tranque 0701, San Guillermo","maps_url":"https://goo.gl/maps/BNEZ5jVAjV453Hru6","kind":"Clase","commune":"Puente Alto"},{"name":"Santa Elvira","address":"Calle Uno 0888","maps_url":"https://goo.gl/maps/nLEVLkcmnmz4owEv6","kind":"Clase","commune":"Puente Alto"},{"name":"Francisco Coloane","address":"San Pedro 3986, esquina Quitalmahue","maps_url":"https://goo.gl/maps/P8HrX4VfEj1GBDPD6","kind":"Clase","commune":"Puente Alto"},{"name":"Pedro Duarte","address":"Las Mosquetas 1817","maps_url":"https://goo.gl/maps/LvWZ76G6kNyQBfLK6","kind":"Clase","commune":"Puente Alto"}]$directorio$::jsonb) AS x(name text,address text,maps_url text,kind text,commune text) LOOP
 SELECT count(*) INTO n FROM public.classes c WHERE (regexp_replace(translate(upper(trim(c.name)),'ÁÉÍÓÚÜ','AEIOUU'),'^(CLASE|LOCAL) +','','g')=translate(upper(r.name),'ÁÉÍÓÚÜ','AEIOUU') OR (r.name='Templo Matriz' AND regexp_replace(translate(upper(trim(c.name)),'ÁÉÍÓÚÜ','AEIOUU'),'^(CLASE|LOCAL) +','','g') IN ('CATEDRAL','TEMPLO MATRIZ','TEMPLO MATRIZ PUENTE ALTO')));
 IF n>1 THEN RAISE EXCEPTION 'Hay más de una coincidencia para %. No se importó nada. Revisa las clases duplicadas.',r.name; END IF;
 IF n=1 THEN
  SELECT c.id INTO clase FROM public.classes c WHERE (regexp_replace(translate(upper(trim(c.name)),'ÁÉÍÓÚÜ','AEIOUU'),'^(CLASE|LOCAL) +','','g')=translate(upper(r.name),'ÁÉÍÓÚÜ','AEIOUU') OR (r.name='Templo Matriz' AND regexp_replace(translate(upper(trim(c.name)),'ÁÉÍÓÚÜ','AEIOUU'),'^(CLASE|LOCAL) +','','g') IN ('CATEDRAL','TEMPLO MATRIZ','TEMPLO MATRIZ PUENTE ALTO')));
  UPDATE public.classes SET address=r.address,commune=r.commune,maps_url=r.maps_url WHERE id=clase;
 ELSE INSERT INTO public.classes(name,kind,address,commune,maps_url) VALUES(r.name,r.kind,r.address,r.commune,r.maps_url);
 END IF;
END LOOP;
END $$;
COMMIT;
SELECT name,kind,address,commune,maps_url FROM public.classes ORDER BY name;
